using System;
using System.IO;
using System.Text;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// accServer reads its cfg\*.json files only as UTF-16 LE: a file in another encoding is ignored and replaced with the
// game's defaults. The panel writes the config templates in UTF-8 when it creates or reinstalls the service, and its
// config editor saves a UTF-16 LE file without the byte order mark. Before every start this script rewrites each
// server\cfg\*.json that is not UTF-16 LE with a BOM. Files that are already right are not touched.
// Never follows links: the service folder belongs to the customer, and this script runs as the monitor.
const long MaxSize = 4 * 1024 * 1024;
string root = (string)ThisService.RootDirectory;
string server = Path.Combine(root, "server");
string cfg = Path.Combine(server, "cfg");

bool IsLink(string path)
{
    return (File.Exists(path) || Directory.Exists(path)) && (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0;
}

string Decode(byte[] b)
{
    if (b.Length >= 3 && b[0] == 0xEF && b[1] == 0xBB && b[2] == 0xBF) return new UTF8Encoding(false).GetString(b, 3, b.Length - 3);
    if (b.Length >= 2 && b[0] == 0xFE && b[1] == 0xFF) return Encoding.BigEndianUnicode.GetString(b, 2, b.Length - 2);
    // No BOM: UTF-16 LE text (what the config editor saves) has a zero high byte on almost every ASCII character.
    int zerosOdd = 0, zerosEven = 0;
    for (int i = 0; i + 1 < b.Length; i += 2) { if (b[i + 1] == 0) zerosOdd++; if (b[i] == 0) zerosEven++; }
    int pairs = b.Length / 2;
    if (b.Length % 2 == 0 && pairs > 0 && zerosOdd * 2 > pairs) return Encoding.Unicode.GetString(b);
    if (b.Length % 2 == 0 && pairs > 0 && zerosEven * 2 > pairs) return Encoding.BigEndianUnicode.GetString(b);
    return new UTF8Encoding(false).GetString(b);
}

if (!Directory.Exists(cfg)) { ScriptConsole.WriteLine((object)"server\\cfg does not exist yet: nothing to convert."); return; }
if (IsLink(server) || IsLink(cfg)) { ScriptConsole.WriteLine((object)"server or server\\cfg is a link: skipped."); return; }

int converted = 0;
foreach (var file in Directory.GetFiles(cfg, "*.json", SearchOption.TopDirectoryOnly))
{
    try
    {
        if (IsLink(file)) { ScriptConsole.WriteLine((object)("Skipped (link): " + Path.GetFileName(file))); continue; }
        var length = new FileInfo(file).Length;
        if (length == 0 || length > MaxSize) continue;
        var bytes = File.ReadAllBytes(file);
        if (bytes.Length >= 2 && bytes[0] == 0xFF && bytes[1] == 0xFE) continue; // already UTF-16 LE with BOM
        var text = Decode(bytes);
        var output = new byte[2 + Encoding.Unicode.GetByteCount(text)];
        output[0] = 0xFF; output[1] = 0xFE;
        Encoding.Unicode.GetBytes(text, 0, text.Length, output, 2);
        // Overwrite in place so the file keeps its owner and permissions.
        using (var fs = new FileStream(file, FileMode.Open, FileAccess.Write, FileShare.Read))
        {
            fs.SetLength(0);
            fs.Write(output, 0, output.Length);
        }
        converted++;
        ScriptConsole.WriteLine((object)("Converted to UTF-16 LE: " + Path.GetFileName(file)));
    }
    catch (Exception ex)
    {
        ScriptConsole.WriteLine((object)("Could not convert " + Path.GetFileName(file) + ": " + ex.Message));
    }
}
ScriptConsole.WriteLine((object)("UTF-16 LE check done, " + converted + " file(s) converted."));

//refAssemblies: TCAdmin.Web.Shared.dll, System.Net.NetworkInformation.dll, System.Net.Primitives.dll, System.Text.Json.dll
using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using System.Text;
using System.Text.Json;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Assetto Corsa Competizione has no server query protocol. The query runs on the monitor of the server that hosts the
// service, so it checks that accServer listens on its TCP port (configuration.json tcpPort, the service's TcpPort).
// Nothing connects to the game, so nothing shows in its console. The server name and track come from cfg\settings.json and cfg\event.json.
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
int port;
try { port = Convert.ToInt32(ThisService.Ports["TcpPort"]); }
catch { port = 0; }

string CfgString(string fileName, string key)
{
    try
    {
        var file = Path.Combine((string)ThisService.RootDirectory, "server", "cfg", fileName);
        if (!File.Exists(file) || new FileInfo(file).Length > 1024 * 1024) return string.Empty;
        var b = File.ReadAllBytes(file);
        string text;
        if (b.Length >= 2 && b[0] == 0xFF && b[1] == 0xFE) text = Encoding.Unicode.GetString(b, 2, b.Length - 2);
        else if (b.Length >= 2 && b[1] == 0) text = Encoding.Unicode.GetString(b);
        else text = new UTF8Encoding(false).GetString(b).TrimStart((char)0xFEFF);
        using (var doc = JsonDocument.Parse(text, new JsonDocumentOptions { AllowTrailingCommas = true, CommentHandling = JsonCommentHandling.Skip }))
            return doc.RootElement.TryGetProperty(key, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : string.Empty;
    }
    catch { return string.Empty; }
}

try
{
    if (port <= 0) throw new Exception("The service has no TcpPort.");
    IPAddress.TryParse(address, out var ip);
    var listening = IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpListeners()
        .Any(l => l.Port == port && (ip == null || l.Address.Equals(ip) || l.Address.Equals(IPAddress.Any) || l.Address.Equals(IPAddress.IPv6Any)));
    if (!listening)
    {
        Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", $"Nothing is listening on {address}:{port} (TCP).");
    }
    else
    {
        var name = CfgString("settings.json", "serverName");
        Globals.ReturnValue = new GameQueryResponse
        {
            Success = true,
            Status = "online",
            Protocol = "custom_script",
            Address = address,
            Hostname = $"{address}:{port}",
            Name = string.IsNullOrWhiteSpace(name) ? ThisService.Name : name,
            GameType = "Assetto Corsa Competizione",
            Map = CfgString("event.json", "track"),
            NumPlayers = 0,
            MaxPlayers = ThisService.Slots,
            NumSpectators = 0,
            MaxSpectators = 0,
            Retries = 0
        };
    }
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}
